// ------------------------------------------------------------------------------------------------- ops

/** `"<ms 16 digits>:<counter 6 digits>:<nodeId>"`; string order is causal order. */
export type Hlc = string

export type Command =
  | { type: 'startMission'; missionId: string }
  | { type: 'approve'; approvalId: string }
  | { type: 'deny'; approvalId: string }
  | { type: 'sendMessage'; missionId: string; to: string | null; body: string }
  | { type: 'takeSteering'; missionAgentId: string }
  | { type: 'releaseSteering'; missionAgentId: string }
  | { type: 'pause'; missionAgentId: string }
  | { type: 'resume'; missionAgentId: string }
  | { type: 'merge'; resultId: string }
  | { type: 'connectAgent'; agentId: string }
  | { type: 'testAgent'; agentId: string }
  | { type: 'switchAgent'; missionAgentId: string; agentId: string }
  | { type: 'addAgent'; missionAgentId: string }
  | { type: 'removeAgent'; missionAgentId: string }
  | { type: 'archiveMission'; missionId: string; archived: boolean }
  | { type: 'deleteMission'; missionId: string }

export type OpBody =
  | { type: 'put'; entity: Entity }
  | { type: 'patch'; entityKind: EntityKind; id: string; fields: Record<string, unknown> }
  | { type: 'delete'; entityKind: EntityKind; id: string }
  | { type: 'command'; node: string; command: Command }
  | { type: 'commandResult'; commandOp: string; ok: boolean; error: string | null }

export interface Op {
  /** A ULID. */
  id: string
  hlc: Hlc
  /** The personId or nodeId that made the op. */
  actor: string
  body: OpBody
}

// ---------------------------------------------------------------------------------------------- frames

export type ClientFrame =
  | { t: 'hello'; workspaceId: string; nodeId: string; cursor: number; token: string | null }
  | { t: 'push'; ops: Op[] }
